import{_t as e,it as t,n,rt as r}from"./chunks/framework.C6TizvAB.js";var i=JSON.parse(`{"title":"Reward","description":"","frontmatter":{"title":"Reward","lang":"en-US"},"headers":[],"relativePath":"maintenance/reward.md","filePath":"maintenance/reward.md"}`),a={name:`maintenance/reward.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="reward" tabindex="-1">Reward <a class="header-anchor" href="#reward" aria-label="Permalink to “Reward”">​</a></h1><p>Maintenance of the reward module consists mainly of cleaning the lines and valves daily, calibrating the valves every 2 weeks, and, when using a mix of condensed milk and water (70/30), cleaning the reward valves and replacing the lines monthly.</p><h2 id="daily-clean" tabindex="-1">Daily clean <a class="header-anchor" href="#daily-clean" aria-label="Permalink to “Daily clean”">​</a></h2><p>Follow this procedure:</p><ol><li><p>Once the day’s training is complete, gently pull the rig’s central stage towards you, leaving some space between you and the rig’s edge. Take the reward spout out of its holder, place it on the edge of the rig’s stage pointing down, and put a beaker under it to collect all the liquid.</p></li><li><p>If milk was prepared that day, pour any remaining milk from the syringes into the milk bottle. Otherwise, empty all of the syringes into the beaker.</p></li><li><p>Take the bottle of H2O2 from the shelf labeled “Cleaning Supplies” and fill the syringe with hydrogen peroxide up to the 40 mL line.</p></li><li><p>When ready, press the “Open Valve” button in the regiment window, or open the valve with the rig tester, and let the H2O2 drain into the beaker.</p></li><li><p>Once the syringe is empty, run a total of 100 mL of distilled water through it, letting it drain into the beaker. When the distilled water reaches the 10 mL line on the syringe, press the “Close Valve” button.</p></li></ol><h2 id="lines-replacement-and-valve-cleaning" tabindex="-1">Lines replacement and valve cleaning <a class="header-anchor" href="#lines-replacement-and-valve-cleaning" aria-label="Permalink to “Lines replacement and valve cleaning”">​</a></h2><p>Do this monthly if you use a mix of condensed milk and water as the reward. We don&#39;t have precise intervals for other reward liquids, but estimate every 2 months for sucrose solutions and much longer for plain water.</p><p>Follow the procedure below:</p><ol><li><p>Drain all liquid from the circuit: first empty the syringe into a waste beaker, then open the valve to release the rest of the liquid into the same beaker.</p></li><li><p>Remove the lines from the syringe to the valve and from the valve to the spout, and use them to measure and cut the new lines from tubing.</p></li><li><p>Clean the valves following the instructions for your model. For the Parker 003-0096-900, fill a syringe with hydrogen peroxide, connect it to the IN port and flush the valve while it is open, then repeat with the syringe filled with air.</p></li><li><p>Use a syringe to flush the spout with hydrogen peroxide, then fill the syringe with air and flush it once more.</p></li><li><p>Install a new syringe and reconnect the circuit with the new lines.</p></li></ol><h2 id="valve-calibration" tabindex="-1">Valve calibration <a class="header-anchor" href="#valve-calibration" aria-label="Permalink to “Valve calibration”">​</a></h2><p>The valve calibration finds the valve opening time that delivers 0.1 mL in total over 25 openings, that is, 4 µL per drop. Follow the steps below.</p><ol><li><p>Gather the following materials: a 1 mL Eppendorf tube with a mark at 0.1 mL, and a blunt metal-tipped syringe.</p></li><li><p>Open MATLAB, then open the <code>solenoidValveCalibration.m</code> and <code>RigParameters</code> files.</p></li><li><p>Make sure the spout is vertical and at the same height as it would be with an animal, place the Eppendorf tube under the reward spout and run the solenoid valve calibration script.</p></li><li><p>Once the run has ended and every drop has been collected, use the blunt metal-tipped syringe to drag any stray drops into the pool at the bottom of the Eppendorf tube. If the milk isn&#39;t at 0.1 mL (over or under), change the duration next to “timeValveOpen =” in the Solenoid Valve Calibration window and click “Run”. Keep adjusting until the milk is at 0.1 mL.</p></li><li><p>Once the milk is close to the 0.1 mL mark, set the <strong>rewardDuration</strong> parameter in the Rig Parameters window to that duration.</p></li><li><p>If you changed the duration, save the Rig Parameters file (Ctrl+S).</p></li></ol><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to “Troubleshooting”">​</a></h2><p>Troubleshoot from the top down: check first for clogs or other problems from the syringe to the valve, then from the valve inlet to the outlet, then from the valve outlet to the spout, and clean or replace parts accordingly.</p>`,14)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};